import {formatPhone} from './domain.js?v=0.5.1';
export function parseTicket(text){const lines=text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),phone=text.match(/(?:\+?1[ .-]?)?\(?\d{3}\)?[ .-]+\d{3}[ .-]+\d{4}/),ticket=text.match(/\bOrder\s*#?\s*(\d+)/i);let address='',name='';const addressIndex=lines.findIndex(l=>/^Address\s*:/i.test(l));if(addressIndex>=0){const rawInline=lines[addressIndex].replace(/^Address\s*:\s*/i,''),inline=/\d/.test(rawInline)?rawInline:'';const next=lines.slice(addressIndex+1,addressIndex+4);address=[inline,...next].filter(Boolean).filter((l,i,a)=>i===0||!/^Seattle\s+WA\s+\d/i.test(l)||!a.slice(0,i).some(x=>/Seattle/i.test(x))).filter(l=>!/^Print Time|^-|^Phone/i.test(l)).join(', ').replace(/,\s*,/g,',');}if(!address){address=lines.find(l=>/^\d{2,6}\s+.*\b(?:AVE|AVENUE|ST|STREET|WAY|RD|ROAD|PL|PLACE|DR|DRIVE|BLVD)\b/i.test(l))||'';}const third=lines.findIndex(l=>/^Third\s*Party\s*:/i.test(l));if(third>0)name=lines[third-1];if(!name){const delivery=lines.findIndex(l=>/Delivery\s*[-–—]+\s*Smile/i.test(l));if(delivery>=0&&lines[delivery+1]&&!/^(Phone|Address|Party|Server|Order)\b/i.test(lines[delivery+1]))name=lines[delivery+1];}name=name.replace(/^[^\p{L}]+/u,'').replace(/\s+[a-z]$/,'').trim();address=address.replace(/(\d)\.(?=\s)/g,'$1').replace(/\s*[:,]+(?=\s*,|$)/g,'').replace(/,\s*,/g,',').trim();return {name,phone:phone?formatPhone(phone[0]):'',address,ticket:ticket?.[1]||''};}
let library;
function loadEngine(){return library??=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('./vendor/ocr/tesseract.min.js',import.meta.url).href;script.onload=resolve;script.onerror=()=>{library=null;script.remove();reject(Error('Scanner unavailable'));};document.head.append(script);});}
export async function scanTicket(file,progress=()=>{}){if(file.size>25e6)throw Error('Photo is too large.');progress('Preparing photo…');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(2,2200/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();await loadEngine();progress('Loading private ticket scanner…');let worker;try{worker=await globalThis.Tesseract.createWorker('eng',1,{workerPath:new URL('./vendor/ocr/worker.min.js',import.meta.url).href,corePath:new URL('./vendor/ocr/',import.meta.url).href,langPath:new URL('./vendor/ocr/',import.meta.url).href,cacheMethod:'none',logger:m=>{if(m.status==='recognizing text')progress(`Reading ticket… ${Math.round(m.progress*100)}%`);}});await worker.setParameters({tessedit_pageseg_mode:'3'});const {data}=await worker.recognize(canvas);let result=parseTicket(data.text);if(!result.phone||!result.address){progress('Taking a closer look at the ticket…');const crop=document.createElement('canvas');crop.width=Math.round(canvas.width*.55);crop.height=Math.round(canvas.height*.76);crop.getContext('2d').drawImage(canvas,canvas.width*.25,canvas.height*.22,crop.width,crop.height,0,0,crop.width,crop.height);await worker.setParameters({tessedit_pageseg_mode:'6'});const focused=parseTicket((await worker.recognize(crop)).data.text);for(const key of ['name','phone','address','ticket'])if(focused[key])result[key]=focused[key];crop.width=0;crop.height=0;}if(!result.name&&!result.phone&&!result.address&&!result.ticket)throw Error('No ticket fields found.');return result;}finally{await worker?.terminate();canvas.width=0;canvas.height=0;}}
